import{_ as a,o as s,c as e,aj as l}from"./chunks/framework.BdtAaXf2.js";const u=JSON.parse('{"title":"JiuwenSwarm 垂直行业技术文章集","description":"","frontmatter":{},"headers":[],"relativePath":"AI人工智能/jiuwenswarm-垂直行业技术文章/README.md","filePath":"AI人工智能/jiuwenswarm-垂直行业技术文章/README.md","lastUpdated":1783611425000,"__rawMarkdown":"# JiuwenSwarm 垂直行业技术文章集\\n\\n基于当前仓库 jiuwenswarm 的最新蜂群（Swarm）技术，撰写的不同垂直行业落地技术文章。每篇文章均**图文并茂**，重点突出 JiuwenSwarm 的最新特性。\\n\\n## 目录结构\\n\\n```\\njiuwenswarm-垂直行业技术文章/\\n├── README.md\\n├── 01-智能制造产线协作/\\n│   ├── 智能制造产线协作：设备依赖编排+角色分工+异构通信安全.md\\n│   └── assets/\\n│       ├── arch-overview.svg         总体架构\\n│       ├── dag-dependency.svg        Swarmflow DAG 依赖图\\n│       ├── symphony-dual-core.svg    Symphony 双核架构\\n│       ├── role-division.svg         Agent Team 角色分工\\n│       ├── security-matrix.svg       异构通信安全矩阵\\n│       ├── roadmap.svg               落地路线图\\n│       ├── swarm-ui.html / .png      集群模式运行界面（截图）\\n│       └── dashboard.html / .png     产线监控大屏（截图）\\n├── 02-餐饮供应链场景/\\n│   ├── 连锁餐饮采购智能编排：食材依赖自动排序+多门店协调+每日补货.md\\n│   └── assets/\\n│       ├── arch-overview.svg         采购协作总体架构\\n│       ├── dag-replenishment.svg     每日补货 Swarmflow DAG\\n│       ├── team-skill-structure.svg  采购 Team Skill 结构\\n│       ├── cron-memory-loop.svg      cron 定时 + 团队记忆闭环\\n│       └── dashboard.html / .png     每日补货协作台（截图）\\n└── 03-法律合规场景/\\n    ├── 合同智能审查与风险追踪：关键条款识别+风险标注+修改建议.md\\n    └── assets/\\n        ├── arch-overview.svg         合同审查总体架构\\n        ├── dag-review.svg            审查 Swarmflow 流程\\n        ├── risk-matrix.svg           条款风险矩阵\\n        └── dashboard.html / .png     合同审查台（截图）\\n```\\n\\n## 已完成文章\\n\\n### 01 · 智能制造产线协作：设备依赖编排 + 角色分工 + 异构通信安全\\n\\n围绕一条\\"电机壳体产线\\"，讲清三件事：设备依赖编排（Swarmflow DAG）、角色分工（Agent Team + 双层团队记忆）、异构通信安全（A2A + 分层权限策略）。\\n\\n重点特性：分布式 Agent Swarm、Swarmflow、Symphony 双核、A2A 协议、工具权限与安全防护、团队记忆。\\n\\n### 02 · 连锁餐饮采购智能编排：食材依赖自动排序 + 多门店协调 + 每日补货\\n\\n围绕连锁餐饮采购，讲清三件事：食材依赖自动排序（Swarmflow + BOM/冷链约束）、多门店协调（TeamSkill 四角色分工 + 并行取数）、每日补货无人值守（cron 定时 + 团队记忆双轮驱动）。\\n\\n重点特性：Swarmflow（map_parallel 并行取数）、TeamSkill 五文件标准、cron 定时任务、双层团队记忆、financial-document-parser 报价单解析。\\n\\n### 03 · 合同智能审查与风险追踪：关键条款识别 + 风险标注 + 修改建议\\n\\n围绕合同审查，讲清三件事：关键条款识别（Swarmflow 三路并行评审）、风险标注与分级（条款库记忆 + 多源判定）、修改建议生成（TeamSkill 四角色 + 条款级改写）。\\n\\n重点特性：Swarmflow（parallel 并行评审 + 条件分支人工复核）、TeamSkill、双层团队记忆（条款库沉淀）、权限分级（高风险 ask）、PDF/OCR 解析。\\n\\n## 图片规范\\n\\n每篇文章的图片分三类来源：\\n\\n1. **SVG 架构图**：统一暗色科技风，在 md 中以相对路径引用。\\n2. **HTML 演示页截图**：编写 HTML+CSS 页面（模拟业务数据）并用无头浏览器截图为 PNG，引入 md。\\n3. **行业实景图**：由作者用 AI 生图工具生成或提供真实素材（如产线照片）。\\n"}'),p={name:"AI人工智能/jiuwenswarm-垂直行业技术文章/README.md"};function r(i,n,m,o,c,t){return s(),e("div",null,[...n[0]||(n[0]=[l("",17)])])}const b=a(p,[["render",r]]);export{u as __pageData,b as default};
